id", "correct": true, "score": 0.9980069003374756, "mean_seconds": 0.011405230925925923, "commit": "e4963ebe4ad9718e99fc5aaba4168b9f20a23b02"}, "source_paths": ["src/candidate.cpp"]}]}}, {"mother": {"action": "read", "decisions": [], "plan_revision": 2, "read": {"evidence_id": "4184453b5e7a41a6", "offset": 0, "operation": "source", "path": "src/candidate.cpp"}, "snapshot_id": "19cee06bd094cec25aec1728445b46c54aa6c2b318437d704d1be45fa2a4fb0b"}}, {"view": {"evidence_id": "4184453b5e7a41a6", "offset": 0, "operation": "source", "path": "src/candidate.cpp", "total_characters": 6762, "text": "#include <algorithm>
